/**
 * Cloning a project (ADR 0012): gates, what is copied and reset, numbering,
 * all-or-nothing quota, and the single announcement with its follow-on effects.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { activityActionSchema, activityFilterSchema } from "@/schemas/activity";
import { cloneProjectSchema } from "@/schemas/project";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(
    registerActivityListeners(),
    registerUsageListeners(),
    searchService.registerSearchListeners(),
  );
});

afterAll(() => {
  for (const off of detachers) off();
  cleanup();
});

const seen: Unsubscribe[] = [];
afterEach(() => {
  while (seen.length > 0) seen.pop()?.();
});

function capture(type: TaskflowEventType): unknown[] {
  const payloads: unknown[] = [];
  seen.push(
    subscribe(type, (payload) => {
      payloads.push(payload);
    }),
  );
  return payloads;
}

function cloneInput(tenant: Tenant, overrides: Partial<CloneProjectInput> = {}): CloneProjectInput {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name: "Platform Next",
    slug: "platform-next",
    key: "PLN",
    includeIssues: true,
    ...overrides,
  };
}

describe("cloneProjectSchema", () => {
  it("defaults includeIssues to true and validates name, slug and key", () => {
    const base = {
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP",
      name: "Copy",
      slug: "copy",
      key: "CPY",
    };
    expect(cloneProjectSchema.parse(base).includeIssues).toBe(true);
    expect(cloneProjectSchema.safeParse({ ...base, key: "toolong" }).success).toBe(false);
    expect(cloneProjectSchema.safeParse({ ...base, name: "x" }).success).toBe(false);
  });

  it("accepts project.cloned as an audit action and filter value", () => {
    expect(activityActionSchema.safeParse("project.cloned").success).toBe(true);
    expect(
      activityFilterSchema.safeParse({
        orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
        action: ["project.cloned"],
        limit: 25,
      }).success,
    ).toBe(true);
  });
});

describe("services/project-service cloneProject", () => {
  it("copies the project's descriptive fields and resets the rest", async () => {
    const tenant = await createTenant("clonefields", "growth");
    const source = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Release train",
      slug: "release-train",
      key: "REL",
      description: "Ship every two weeks",
      visibility: "private",
      leadId: tenant.userIds.admin,
      color: "#112233",
      targetDate: "2026-12-01T00:00:00.000Z" as IsoTimestamp,
    });
    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: source.id,
      status: "paused",
    });

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { projectId: source.id, name: "Release train 2", slug: "rt-2", key: "RT2" }),
    );

    expect(clone.id).not.toBe(source.id);
    expect(clone).toMatchObject({
      orgId: tenant.org.id,
      name: "Release train 2",
      slug: "rt-2",
      key: "RT2",
      description: "Ship every two weeks",
      visibility: "private",
      leadId: tenant.userIds.admin,
      color: "#112233",
      status: "active",
      startsAt: null,
      targetDate: null,
      archivedAt: null,
    });
    expect(await projectRepo.findProjectById(tenant.org.id, clone.id)).toEqual(clone);
  });

  it("makes a taken slug unique by suffix", async () => {
    const tenant = await createTenant("cloneslug", "growth");
    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { slug: "platform" }),
    );
    expect(clone.slug).toBe("platform-2");
  });

  it("copies live issues as a fresh start, numbered from 1 in source order", async () => {
    const tenant = await createTenant("cloneissues", "growth");
    const member = tenant.actors.member;
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "bug",
      color: "#ff0000",
      description: null,
    });

    const first = await issueService.createIssue(member, {
      ...issueInput(tenant.org.id, tenant.project.id, {
        title: "First issue",
        assigneeId: tenant.userIds.admin,
        dueAt: "2026-06-01T00:00:00.000Z",
      }),
      description: "Describe it",
      priority: "high",
      estimate: 5,
      labelIds: [label.id],
    });
    const second = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Second issue (archived)" }),
    );
    const third = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Third issue" }),
    );
    await issueService.changeIssueStatus(member, {
      orgId: tenant.org.id,
      issueId: first.id,
      status: "done",
    });
    await issueService.archiveIssue(member, tenant.org.id, second.id);

    const clone = await projectService.cloneProject(member, cloneInput(tenant));

    const copies = await issueRepo.listLiveIssuesForProject(tenant.org.id, clone.id);
    expect(copies.map((issue) => [issue.number, issue.title])).toEqual([
      [1, "First issue"],
      [2, "Third issue"],
    ]);

    const [copyOfFirst] = copies;
    expect(copyOfFirst).toMatchObject({
      description: "Describe it",
      priority: "high",
      estimate: 5,
      dueAt: first.dueAt,
      labelIds: [label.id],
      status: "backlog",
      assigneeId: null,
      parentId: null,
      startedAt: null,
      completedAt: null,
      authorId: tenant.userIds.member,
      archivedAt: null,
    });
    expect(copyOfFirst?.id).not.toBe(first.id);

    // The next issue created in the clone continues after the copies.
    const next = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, clone.id, { title: "Fourth issue" }),
    );
    expect(next.number).toBe(3);

    // The source is untouched.
    const sourceIssues = await issueRepo.listLiveIssuesForProject(tenant.org.id, tenant.project.id);
    expect(sourceIssues.map((issue) => [issue.id, issue.number, issue.status])).toEqual([
      [first.id, 1, "done"],
      [third.id, 3, "backlog"],
    ]);
    expect(
      (await issueRepo.findIssueById(tenant.org.id, first.id))?.assigneeId,
    ).toBe(tenant.userIds.admin);
  });

  it("starts copies in the workspace's default issue status", async () => {
    const tenant = await createTenant("clonedefault", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Only issue" }),
    );
    const { getDb } = await import("@/server/db");
    getDb()
      .$client.prepare("UPDATE organizations SET default_issue_status = 'todo' WHERE id = ?")
      .run(tenant.org.id);

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));
    const copies = await issueRepo.listLiveIssuesForProject(tenant.org.id, clone.id);
    expect(copies.map((issue) => issue.status)).toEqual(["todo"]);
  });

  it("copies every live issue, not just the first page", async () => {
    const tenant = await createTenant("clonebig", "growth");
    for (let i = 1; i <= 120; i += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Issue ${i}` }),
        tenant.userIds.member,
        i,
      );
    }

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));
    const copies = await issueRepo.listLiveIssuesForProject(tenant.org.id, clone.id);
    expect(copies).toHaveLength(120);
    expect(copies.map((issue) => issue.number)).toEqual(
      Array.from({ length: 120 }, (_, index) => index + 1),
    );
    expect(copies[119]?.title).toBe("Issue 120");
  });

  it("copies no issues when includeIssues is false", async () => {
    const tenant = await createTenant("clonebare", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Stay behind" }),
    );

    const events = capture("project.cloned");
    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { includeIssues: false }),
    );

    expect(await issueRepo.countIssues(tenant.org.id, clone.id, { includeArchived: true })).toBe(0);
    expect(events).toMatchObject([{ projectId: clone.id, issuesCopied: 0 }]);
  });

  it("publishes only project.cloned, on behalf of the person cloning", async () => {
    const tenant = await createTenant("cloneevent", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "One" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Two" }),
    );

    const cloned = capture("project.cloned");
    const created = capture("project.created");
    const issueCreated = capture("issue.created");

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    expect(created).toHaveLength(0);
    expect(issueCreated).toHaveLength(0);
    expect(cloned).toHaveLength(1);
    expect(cloned[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: clone.id,
      sourceProjectId: tenant.project.id,
      issuesCopied: 2,
    });
  });

  it("records one audit entry under the new project", async () => {
    const tenant = await createTenant("cloneaudit", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "One" }),
    );

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    const page = await activityRepo.listActivity({
      orgId: tenant.org.id,
      projectId: clone.id,
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "project.cloned",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: clone.id,
      projectId: clone.id,
      metadata: { sourceProjectId: tenant.project.id, issuesCopied: 1 },
    });
  });

