    const tenant = await createTenant("clonesearch", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Quokka migration" }),
      tenant.userIds.member,
      1,
    );
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Quokka cleanup" }),
      tenant.userIds.member,
      2,
    );
    await usageRepo.recomputeUsage(tenant.org.id);
    const before = await usageRepo.getUsage(tenant.org.id);

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { name: "Wombat Next" }),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Quokka",
      kinds: ["issue"],
      projectId: clone.id,
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(2);

    const projectHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Wombat",
      kinds: ["project"],
      limit: 25,
      cursor: null,
    });
    expect(projectHits.items.map((hit) => hit.id)).toEqual([clone.id]);

    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.projectsUsed).toBe(before.projectsUsed + 1);
    expect(after.issuesUsed).toBe(before.issuesUsed + 2);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(recounted.projectsUsed).toBe(after.projectsUsed);
    expect(recounted.issuesUsed).toBe(after.issuesUsed);
  });

  it("refuses the whole clone when the copies would not fit the issue quota", async () => {
    // Free plan: 100 issues per project, 2 projects (one already exists).
    const tenant = await createTenant("clonequota", "free");
    for (let i = 1; i <= 101; i += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Bulk ${i}` }),
        tenant.userIds.member,
        i,
      );
    }
    const cloned = capture("project.cloned");

    await expect(
      projectService.cloneProject(tenant.actors.member, cloneInput(tenant)),
