    const tenant = await createTenant("clonepq", "free");
    await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    await expect(
      projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant, { name: "Third", slug: "third", key: "THD" }),
      ),
    ).rejects.toThrow(/allows 2 projects/);
  });

  it("needs permission to create a project", async () => {
    const tenant = await createTenant("clonedenied", "growth");
    await expect(
      projectService.cloneProject(tenant.actors.viewer, cloneInput(tenant)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await projectRepo.findProjectBySlug(tenant.org.id, "platform-next")).toBeNull();
  });

  it("refuses an archived source and a source from another workspace", async () => {
    const tenant = await createTenant("clonearch", "growth");
    const other = await createTenant("cloneother", "growth");

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      projectService.cloneProject(tenant.actors.member, cloneInput(tenant)),
    ).rejects.toThrow(/already archived/);

    await expect(
      projectService.cloneProject(
        tenant.actors.member,
        cloneInput(other, { orgId: other.org.id }),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      projectService.cloneProject(
        other.actors.member,
        cloneInput(other, { projectId: tenant.project.id }),
      ),
    ).rejects.toThrow(/not found/);
  });

  it("leaves nothing behind when the key is already taken", async () => {
    const tenant = await createTenant("clonekey", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "One" }),
    );

    await expect(
      projectService.cloneProject(tenant.actors.member, cloneInput(tenant, { key: "PLAT" })),
    ).rejects.toThrow();

    expect(await projectRepo.findProjectBySlug(tenant.org.id, "platform-next")).toBeNull();
  });
});

