    );

    const cloned = capture("project.cloned");
    const created = capture("project.created");
    const issueCreated = capture("issue.created");

    const clone = await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    expect(created).toHaveLength(0);
    expect(issueCreated).toHaveLength(0);
    expect(cloned).toHaveLength(1);
