import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { activityActionSchema, activityFilterSchema } from "@/schemas/activity";
import { cloneProjectSchema } from "@/schemas/project";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(
    registerActivityListeners(),
    registerUsageListeners(),
    searchService.registerSearchListeners(),
  );
});

afterAll(() => {
  for (const off of detachers) off();
  cleanup();
});

const seen: Unsubscribe[] = [];
afterEach(() => {
  while (seen.length > 0) seen.pop()?.();
});

function capture(type: TaskflowEventType): unknown[] {
  const payloads: unknown[] = [];
  seen.push(
    subscribe(type, (payload) => {
      payloads.push(payload);
    }),
  );
  return payloads;
}

function cloneInput(tenant: Tenant, overrides: Partial<CloneProjectInput> = {}): CloneProjectInput {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name: "Platform Next",
    slug: "platform-next",
    key: "PLN",
    includeIssues: true,
    ...overrides,
  };
}

describe("cloneProjectSchema", () => {
  it("defaults includeIssues to true and validates name, slug and key", () => {
    const base = {
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP",
      name: "Copy",
      slug: "copy",
      key: "CPY",
    };
    expect(cloneProjectSchema.parse(base).includeIssues).toBe(true);
    expect(cloneProjectSchema.safeParse({ ...base, key: "toolong" }).success).toBe(false);
    expect(cloneProjectSchema.safeParse({ ...base, name: "x" }).success).toBe(false);
  });

  it("accepts project.cloned as an audit action and filter value", () => {
    expect(activityActionSchema.safeParse("project.cloned").success).toBe(true);
    expect(
      activityFilterSchema.safeParse({
        orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
        action: ["project.cloned"],
        limit: 25,
      }).success,
    ).toBe(true);
  });
});

